+      subscriptions: [],
+    });
+
+    const listed = await call("list_goals", {}, ASKED_IN.threadId);
+    expect(listed.isError).toBe(false);
+    expect(listed.text).toContain(goal?.id ?? "missing");
+
+    // A field left blank in a change is left as it was.
