+import { afterEach, expect, test } from "bun:test";
+import { BuiltInAgentWithSaneHistory } from "@openbot/toolkit/copilotkit/agents";
+import { tap } from "rxjs";
+import { z } from "zod";
+import {
+  builtInAgentConfiguration,
+  runtimeModelForEnvironment,
+} from "./copilot";
+import {
+  configureModelMeasurement,
+  inMeasuredTurn,
+  type ModelMeasurement,
+} from "./measurement/model";
+import {
+  createTurnScheduling,
+  RoutinePreemptedError,
+} from "./scheduling/turns";
+
+const names = [
+  "OPENAI_BASE_URL",
+  "COPILOTKIT_OPENAI_API",
+  "OPENBOT_OPENAI_STATELESS",
+] as const;
+const saved = names.map((name) => process.env[name]);
+afterEach(() => {
+  configureModelMeasurement(undefined);
+  names.forEach((name, index) => {
+    if (saved[index] === undefined) delete process.env[name];
+    else process.env[name] = saved[index];
+  });
+});
+
+type Item = Record<string, unknown>;
+
+// Minimal Responses SSE with the same commentary-before-tool shape seen at the relay.
+function responseStream(step: number, omitUsage = false) {
+  const text = step === 0 ? "Starting probe." : "PROBE_OK";
+  const message = {
+    id: `msg_probe_${step}`,
+    type: "message",
+    role: "assistant",
+    status: "completed",
+    phase: step === 0 ? "commentary" : "final_answer",
+    content: [{ type: "output_text", text, annotations: [] }],
+  };
+  const call = {
+    id: `fc_probe_${step}`,
+    type: "function_call",
+    call_id: `call_probe_${step}`,
+    name: step === 0 ? "probe_first" : "probe_second",
+    arguments: "{}",
+    status: "completed",
+  };
+  const reasoning = {
+    id: "rs_probe",
+    type: "reasoning",
+    summary: [],
+    encrypted_content: "opaque-reasoning",
+  };
+  const output =
+    step === 0 ? [reasoning, message, call] : step === 1 ? [call] : [message];
+  const response = {
+    id: `resp_probe_${step}`,
+    model: "gpt-6.1-sol",
+    created_at: 1794045000,
+    output,
+  };
+  const events: Item[] = [{ type: "response.created", response }];
+  output.forEach((item, index) => {
+    events.push({
+      type: "response.output_item.added",
+      item,
+      output_index: index,
+    });
+    if (item.type === "message") {
+      events.push({
+        type: "response.output_text.delta",
+        item_id: item.id,
+        output_index: index,
+        content_index: 0,
+        delta: text,
+      });
+    } else if (item.type === "function_call") {
+      events.push({
+        type: "response.function_call_arguments.delta",
+        item_id: item.id,
+        output_index: index,
+        delta: "{}",
+      });
+    }
+    events.push({
+      type: "response.output_item.done",
+      item,
+      output_index: index,
+    });
+  });
+  events.push({
+    type: "response.completed",
+    response: {
+      ...response,
+      status: "completed",
+      ...(!omitUsage
+        ? {
+            usage: {
+              input_tokens: 10,
+              output_tokens: 5,
+              total_tokens: 15,
+              input_tokens_details: { cached_tokens: 4 },
+            },
+          }
+        : {}),
+    },
+  });
+  return new Response(
+    events
+      .map(
+        (event) => `event: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`,
+      )
+      .join(""),
+    { headers: { "content-type": "text/event-stream" } },
+  );
+}
